verify.cmd:
node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ").replace(/\s+/g," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const act=rd("app/(main)/spaces/[slug]/settings/calendar/vera-calendar-actions.ts")
const box=rd("components/spaces/vera-calendar-box.tsx")
const raw=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return null}}
const rawVoc=raw("lib/calendar/vera-command.ts"),rawAct=raw("app/(main)/spaces/[slug]/settings/calendar/vera-calendar-actions.ts")
if(act===null||rawVoc===null||rawAct===null)process.exit(79)
import("@/lib/calendar/vera-command.ts").then((v)=>{
if(typeof v.isDestructiveChange!=="function")fail("nothing names which changes are destructive, so archive is back in the same basket as a retitle")
const PLAN="11111111-1111-4111-8111-111111111111"
// RUN the rule rather than grep for its name: archive and Cancelled are destructive, a retitle is not.
if(v.isDestructiveChange({kind:"archive",planId:PLAN})!==true)fail("archiving a Plan is no longer destructive, so it arrives pre-ticked and the server applies it without a second box")
if(v.isDestructiveChange({kind:"stage",planId:PLAN,stage:"cancelled"})!==true)fail("setting a Plan to Cancelled is no longer destructive, and Cancelled archives the Plan and every date on it")
if(v.isDestructiveChange({kind:"retitle",planId:PLAN,title:"x"})!==false)fail("an ordinary retitle is now treated as destructive, so the second box means nothing")
if(typeof v.parseVeraConfirmed!=="function")fail("the confirmation set is not parsed, so whatever the browser sends is taken at its word")
// The confirmation set is PARSED, not trusted: out-of-range, non-integer and non-number entries go.
const set=v.parseVeraConfirmed([0,"1",2.5,-1,9,1],2)
if(!(set instanceof Set)||set.has(9)||set.has(-1)||set.has(2.5)||set.has("1")||!set.has(0)||!set.has(1))fail("parseVeraConfirmed takes the browser at its word: a confirmation index it never showed, a string or a fraction now counts as a confirmation")
if(v.parseVeraConfirmed("all",2).size!==0)fail("a confirmation payload that is not a list is still read as confirming something")
if(typeof v.destructiveConfirmation!=="function"||!v.destructiveConfirmation({kind:"archive",planId:PLAN},{plans:{},entries:{},current:{}}))fail("a destructive line carries no confirmation of its own, so there is nothing for the server to demand back")
// The preview names the real subject; the fallback is what it says when nothing named it.
if(typeof v.buildVeraDescribeContext!=="function")fail("the preview can fall back to an unnamed object with nothing building the real titles")
const ctx=v.buildVeraDescribeContext([{kind:"retitle",planId:PLAN,title:"Winter sits"}],{plan:{[PLAN]:{title:"Autumn sits"}},entry:{}})
if(!/Autumn sits/.test(v.describeChange({kind:"retitle",planId:PLAN,title:"Winter sits"},ctx)))fail("a proposal line no longer names the Plan it will change, so a person ticks \x22that Plan\x22 without being told which")
// The gate that matters is the SERVER’s; a disabled checkbox is not a gate.
if(!/isDestructiveChange\(change\) && !confirmed\.has\(i\)/.test(act))fail("the SERVER no longer refuses an unconfirmed destructive line: the gate is back to being only a disabled button")
if(box!==null&&!/checked: ?data\.changes\.map\(\(change\) => !isDestructiveChange\(change\)\)/.test(box))fail("proposal lines arrive pre-ticked again, so the default action is apply-all")
// The normalising read strips comments, and this claim IS a comment, so both arms read the raw file.
if(/Nothing is written here/.test(rawAct))fail("the false invariant comment is back on the propose door")
if(/Nothing is written here/.test(rawVoc))fail("the false invariant comment is back in the Vera vocabulary")
process.exit(0)
}).catch((e)=>{console.error("probe could not look: "+e.message);process.exit(79)})'
